style.css:
@-moz-document domain("youtube.com") {
/* Define RosÃ©Â Pine palette variables.  These are based on the main
     RosÃ©Â Pine paletteã€983713867094583â€ L69-L107ã€‘ and can be adjusted for
     Moon or Dawn variants by changing the hex values. */
  :root {
    --rp-base:      #191724; /* primary background */
    --rp-surface:   #1f1d2e; /* secondary background */
    --rp-overlay:   #26233a; /* tertiary background */
    --rp-muted:     #6e6a86; /* low contrast text */
    --rp-subtle:    #908caa; /* medium contrast text */
    --rp-text:      #e0def4; /* high contrast text */
    --rp-love:      #eb6f92; /* accent â€“ errors */
    --rp-gold:      #f6c177; /* accent â€“ warnings */
    --rp-rose:      #ebbcba; /* accent â€“ highlights */
    --rp-pine:      #31748f; /* accent â€“ links */
    --rp-foam:      #9ccfd8; /* accent â€“ info */
    --rp-iris:      #c4a7e7; /* accent â€“ hints */
    --rp-highlight-low:  #21202e; /* low contrast highlight */
    --rp-highlight-med:  #403d52; /* medium contrast highlight */
    --rp-highlight-high: #524f67; /* high contrast highlight */
  }

  /* Base body and containers */
  body,
  ytd-app,
  #page-manager,
  #primary,
  #secondary {
    background-color: var(--rp-base) !important;
    color: var(--rp-text) !important;
  }

  /* Header (masthead) */
  #masthead-container,
  ytd-masthead {
    background-color: var(--rp-surface) !important;
    color: var(--rp-text) !important;
  }

  /* Guide (left sidebar) */
  #guide,
  ytd-guide-renderer,
  ytd-mini-guide-renderer {
    background-color: var(--rp-surface) !important;
    color: var(--rp-text) !important;
  }

  /* Top search bar */
  ytd-searchbox {
    background-color: var(--rp-overlay) !important;
  }
  ytd-searchbox input {
    background-color: transparent !important;
    color: var(--rp-text) !important;
  }

  /* Video thumbnails and watch pages */
  ytd-thumbnail,
  ytd-rich-item-renderer,
  ytd-rich-grid-media,
  ytd-video-renderer,
  ytd-compact-video-renderer {
    background-color: var(--rp-surface) !important;
    color: var(--rp-text) !important;
  }

  /* Buttons, icons and interactive elements */
  button,
  ytd-toggle-button-renderer,
  ytd-button-renderer {
    background-color: var(--rp-overlay) !important;
    color: var(--rp-text) !important;
    border-color: var(--rp-highlight-high) !important;
  }
  button:hover,
  ytd-toggle-button-renderer:hover,
  ytd-button-renderer:hover {
    background-color: var(--rp-highlight-med) !important;
  }

  /* Links and clickable text */
  a,
  yt-formatted-string a,
  ytd-thumbnail a {
    color: var(--rp-pine) !important;
  }
  a:hover {
    color: var(--rp-rose) !important;
  }

  /* Badges such as LIVE and PREMIERE */
  .badge,
  #time-status[aria-label="LIVE"],
  .badge-shape-wiz--live {
    background-color: var(--rp-love) !important;
    color: var(--rp-base) !important;
  }

  /* Comments section */
  #comments,
  ytd-comments {
    background-color: var(--rp-base) !important;
    color: var(--rp-text) !important;
  }
  ytd-comment-renderer {
    background-color: var(--rp-surface) !important;
    color: var(--rp-text) !important;
  }

  /* Scrollbars */
  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  ::-webkit-scrollbar-track {
    background: var(--rp-highlight-low);
  }
  ::-webkit-scrollbar-thumb {
    background-color: var(--rp-highlight-high);
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background-color: var(--rp-highlight-med);
  }

  /* Dialogs and popups (e.g. login prompts) */
  tp-yt-paper-dialog,
  ytd-popup-container {
    background-color: var(--rp-surface) !important;
    color: var(--rp-text) !important;
  }
  tp-yt-paper-dialog .paper-dialog-scrollable {
    background-color: var(--rp-surface) !important;
  }

  /* Notification and menu panels */
  ytd-notification-topbar-button-renderer,
  #container.ytd-notification-topbar-button-renderer,
  ytd-menu-popup-renderer {
    background-color: var(--rp-surface) !important;
    color: var(--rp-text) !important;
  }
  ytd-menu-popup-renderer::before {
    background-color: var(--rp-surface) !important;
  }

  /* Chips (topics on home page) */
  ytd-feed-filter-chip-bar-renderer,#chips {
    background-color: var(--rp-base) !important;
  }
  ytd-chip-cloud-chip-renderer {
    background-color: var(--rp-overlay) !important;
    color: var(--rp-text) !important;
  }
  ytd-chip-cloud-chip-renderer[selected] {
    background-color: var(--rp-pine) !important;
    color: var(--rp-base) !important;
  }

  /* Progress bars (video watched indicator) */
  .ytd-thumbnail-overlay-resume-playback-renderer {
    background: var(--rp-pine) !important;
  }
  .ytd-thumbnail-overlay-resume-playback-renderer::after {
    background: var(--rp-pine) !important;
  }

  /* Player controls */
  #movie_player .ytp-chrome-bottom {
    background: var(--rp-surface) !important;
  }
  #movie_player .ytp-progress-bar-container {
    background: var(--rp-overlay) !important;
  }
  #movie_player .ytp-progress-bar-container .ytp-progress-bar {
    color: var(--rp-pine) !important;
  }
  #movie_player .ytp-progress-list .ytp-play-progress {
    background-color: var(--rp-pine) !important;
  }
  #movie_player .ytp-progress-list .ytp-load-progress {
    background-color: var(--rp-highlight-med) !important;
  }
  #movie_player .ytp-chrome-controls .ytp-button {
    color: var(--rp-text) !important;
  }
  #movie_player .ytp-chrome-controls .ytp-button:hover {
    color: var(--rp-rose) !important;
  }
}
